library(tidyverse)
library(edgeR)
library(GenomicRanges)
library(plyranges)
library(ggpubr)

# Output directory for plots
out_dir <- "/net/nfs-irwrsrchnas01/labs/dschones/bioresearch/qianhui/projects/PMM/DNAm/eRRBS_hg38_p14_bowtie1_filter/methylKit_output/plots"
if (!dir.exists(out_dir)) dir.create(out_dir, recursive = TRUE)

# ------------------------------------------------------------------------------
# 1. Get eRRBS Region Mean DNAm (Active L1 Upstream)
# ------------------------------------------------------------------------------
# Files generated by eRRBS_region_mean_DNAm.sh
mean_DNAm_files <- list.files("/net/nfs-irwrsrchnas01/labs/dschones/bioresearch/qianhui/projects/PMM/DNAm/eRRBS_hg38_p14_bowtie1_filter/methylKit_output/region_mean",
    pattern = "10kb_avg_DNAm.tsv", full.names = TRUE
)

mean_DNAm_sample_ls <- list()
for (i in seq_along(mean_DNAm_files)) {
    # Filename format: {sample}_10kb_avg_DNAm.tsv
    sample_name <- str_remove(basename(mean_DNAm_files[i]), "_10kb_avg_DNAm.tsv")

    # Read file: col1=ID, col6=mean0 (mean coverage?) -> usage in ref script: select(X1, X6) -> te_id, mean_DNAm
    # bigWigAverageOverBed output: name, size, covered, sum, mean0, mean
    # col6 is 'mean' (average over the item, with 0 for uncovered bases? or just covered?)
    # Ref script selected X6. bigWigAverageOverBed columns:
    # 1:name 2:size 3:covered 4:sum 5:mean0 6:mean
    # So X6 is 'mean' (average value of the bed graph items covering the region).

    s <- read_tsv(mean_DNAm_files[i], col_names = FALSE, show_col_types = FALSE) %>%
        dplyr::select(X1, X6)
    colnames(s) <- c("te_id", "mean_DNAm")
    mean_DNAm_sample_ls[[sample_name]] <- s
}

mean_DNAm_sample <- mean_DNAm_sample_ls %>%
    bind_rows(.id = "sample")

# ------------------------------------------------------------------------------
# 2. Get Antisense L1 Upstream 10kb Expression
# ------------------------------------------------------------------------------
# Using the same path as reference script
mean_expr_files <- list.files("/net/nfs-irwrsrchnas01/labs/dschones/bioresearch/qianhui/projects/PMM/RNA/RNA_hg38_p14_fastp_2passStar_sameAsMMRFpipe/antisenseTE_expr/up10kb_antisense_expr",
    pattern = "up10kb_counts.txt$", full.names = TRUE
)

mean_expr_sample_ls <- list()
for (j in seq_along(mean_expr_files)) {
    sample_name <- str_remove(basename(mean_expr_files[j]), "_antisenseTE_up..+")

    s_g <- read.table(mean_expr_files[j], stringsAsFactors = FALSE, header = TRUE)
    colnames(s_g) <- c("te_id", "Chr", "Start", "End", "Strand", "Length", "crick", "watson")

    s_g <- s_g %>%
        dplyr::mutate(totalCount = crick + watson) %>%
        dplyr::select(te_id, Length, totalCount)

    mean_expr_sample_ls[[sample_name]] <- s_g
}

mean_expr_sample <- mean_expr_sample_ls %>%
    bind_rows(.id = "sample")

# ------------------------------------------------------------------------------
# 3. Process Expression (Counts -> LCPM)
# ------------------------------------------------------------------------------
mean_expr_matrix <- mean_expr_sample %>%
    pivot_wider(id_cols = te_id, names_from = sample, values_from = totalCount) %>%
    column_to_rownames(var = "te_id") %>%
    as.matrix()

# Calculate CPM then log2-CPM
cpm_mean_expr_matrix <- cpm(mean_expr_matrix)
lcpm_mean_expr_matrix <- log2(cpm_mean_expr_matrix + 1)

# Reshape back to long format
lcpm_mean_expr_long <- lcpm_mean_expr_matrix %>%
    as.data.frame() %>%
    rownames_to_column(var = "te_id") %>%
    pivot_longer(cols = -c(te_id), names_to = "sample", values_to = "lcpm")

# Join LCPM back to sample info
mean_expr_sample_final <- mean_expr_sample %>%
    left_join(lcpm_mean_expr_long, by = c("sample", "te_id"))

# ------------------------------------------------------------------------------
# 4. Bind DNAm and Expression for Correlation
# ------------------------------------------------------------------------------
# Join DNAm data to Expression data
# Note: Use inner_join or left_join depending on if we want only samples present in both
# Since we are plotting eRRBS correlation, we primarily care about samples where we HAVE DNAm.
activeL1_antisense <- read_tsv("/net/nfs-irwrsrchnas01/labs/dschones/bioresearch/qianhui/projects/PMM/RNA/RNA_hg38_p14_fastp_2passStar_sameAsMMRFpipe_uniqueMap/activationScore/filtered_L1/antisense_L1s.tsv")

activeL1_antisense_PMM <- activeL1_antisense %>%
    dplyr::filter(str_detect(sampleID, "PMM"))

sample_mean <- mean_DNAm_sample %>%
    dplyr::mutate(sample = str_replace(sample, "^NPC", "BMPC")) %>%
    inner_join(mean_expr_sample_final, by = c("sample", "te_id")) %>%
    dplyr::filter(te_id %in% unique(activeL1_antisense$Geneid))

# Check if we have data
if (nrow(sample_mean) == 0) {
    stop("No common samples found between DNAm and RNA expression files. Check sample naming.")
}

# ------------------------------------------------------------------------------
# 5. Plotting
# ------------------------------------------------------------------------------

# General Plot (All samples)
sample_mean_cor <- sample_mean %>%
    ggplot(aes(x = lcpm, y = mean_DNAm)) +
    geom_point(alpha = 0.5) +
    geom_smooth(
        method = "lm", se = FALSE,
        color = "grey70", linetype = "dashed"
    ) +
    stat_cor(method = "spearman", size = 3, label.y = 1.1) +
    labs(
        title = "eRRBS: L1 Upstream DNAm vs Expression",
        x = "Mean expression (lcpm)",
        y = "Mean DNA methylation"
    ) +
    theme_pubr(base_size = 12)

ggsave(file.path(out_dir, "eRRBS_sample_DNAm_expr_mean_Cor.pdf"),
    plot = sample_mean_cor,
    device = "pdf", width = 12, height = 10, units = "cm"
)

# Faceted Plot (Per Sample)
# Assuming we want to see individual correlations for checks
facet_sample_mean_cor <- sample_mean %>%
    ggplot(aes(x = lcpm, y = mean_DNAm)) +
    geom_point(alpha = 0.3) +
    # geom_smooth(method = "lm") +
    geom_smooth(
        method = "lm", se = FALSE,
        color = "grey70", linetype = "dashed"
    ) +
    stat_cor(method = "spearman", size = 3, label.y = 1.1) +
    facet_wrap(~sample, scales = "fixed") +
    labs(x = "Mean expression (lcpm)", y = "Mean DNA methylation") +
    theme_pubr(base_size = 12)

ggsave(file.path(out_dir, "eRRBS_facet_sample_DNAm_expr_mean_Cor.pdf"),
    plot = facet_sample_mean_cor,
    device = "pdf", width = 15, height = 6, units = "cm"
)

message("Plots saved to: ", out_dir)
